标准 Node.js ES module 执行以下程序。返回 order（out无分隔拼接的字符串）、syncPrefix（所有同步写入拼接）。解释Promise链、queueMicrotask和两处await job恢复的入队顺序；解释应与最终字符串每个字符对应。
const out=['S'];
const job=Promise.resolve().then(()=>{out.push('P');queueMicrotask(()=>out.push('Q'));}).then(()=>out.push('R'));
(async()=>{out.push('A');await job;out.push('B');})();
queueMicrotask(()=>{out.push('C');Promise.resolve().then(()=>out.push('D'));});
out.push('T');
await job;out.push('U');
await Promise.resolve();out.push('V');
await new Promise(r=>setTimeout(r,0));
console.log(out.join(''));
